                    .offset_from((*op).offset(ll_totalCost as isize))
                    as c_long as size_t;
                let maxMlSize: size_t = ((MINMATCH as c_uint)
                    .wrapping_add(ML_MASK.wrapping_sub(1 as c_uint))
                    as size_t)
                    .wrapping_add(bytesLeftForMl.wrapping_mul(255 as size_t));
